process_real_datasets_consecutive_loss() {
    local n_val="$1"
    local percentage="$2"
    process_real_datasets_generic \
        "run_calc_loss_consecutive" \
        "$n_val" \
        "$percentage" \
        "_consecutive" \
        "_consecutive" \
